frappe.ui.form.on('Daily Work Allocation', {
    after_save: function(frm) {
        console.log("=== DWA After Save Triggered ===");
        console.log("Form Data:", frm.doc);
        
        // Check if Work child table has entries
        if (!frm.doc.custom_work_allocation || frm.doc.custom_work_allocation.length === 0) {
            console.log("No work allocation entries found");
            return;
        }
        
        console.log("Work Allocation Entries:", frm.doc.custom_work_allocation);
        
        // Get employee name and date from Daily Work Allocation
        let employee_name = frm.doc.employee_name;
        let allocation_date = frm.doc.date; // Get the date from Daily Work Allocation

        console.log("Employee Name:", employee_name);
        console.log("Allocation Date:", allocation_date);

        // First, get the user_id from employee name for task assignment
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Employee',
                fieldname: 'user_id',
                filters: {'name': employee_name}
            },
            callback: function(emp_response) {
                console.log("Employee response:", emp_response);
                let user_id = null;
                if (emp_response && emp_response.message && emp_response.message.user_id) {
                    user_id = emp_response.message.user_id;
                }
                console.log("Employee User ID:", user_id);
                
                // Iterate through each work allocation entry
                frm.doc.custom_work_allocation.forEach((work_item, index) => {
                    console.log(`\n=== Processing Work Item ${index + 1} ===`);
                    console.log("Work Item Data:", work_item);
                    
                    // Check if task already exists for this work item
                    let task_subject = work_item.work_title;
                    let task_project = work_item.project_title;
                    
                    console.log("Checking for existing task with subject:", task_subject);
                    
                    frappe.call({
                        method: 'frappe.client.get_list',
                        args: {
                            doctype: 'Task',
                            filters: {
                                subject: task_subject,
                                project: task_project
                            },
                            fields: ['name']
                        },
                        callback: function(r) {
                            console.log("Existing task check result:", r.message);
                            
                            if (r.message && r.message.length > 0) {
                                console.log("Task already exists, skipping creation");
                                return;
                            }
                            
                            console.log("Creating new task...");
                            
                            // Create new task with date from Daily Work Allocation
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: {
                                    doc: {
                                        doctype: 'Task',
                                        subject: work_item.work_title,
                                        description: work_item.work_description,
                                        project: task_project,
                                        // Map Work table's expected_start_date to Task's custom field
                                        custom_expected_start_time: work_item.expected_start_date,
                                        expected_time: work_item.expected_time_in_hours,
                                        // Add the date from Daily Work Allocation
                                        exp_start_date: allocation_date, // This will set the date in Task
                                        // You can also set it to task_creation_date if you have that field
                                        // task_creation_date: allocation_date,
                                        status: 'Open'
                                    }
                                },
                                callback: function(task_response) {
                                    console.log("Task creation response:", task_response);
                                    
                                    if (task_response && task_response.message) {
                                        console.log("Task created successfully:", task_response.message);
                                        
                                        if (user_id) {
                                            let task_name = task_response.message.name;
                                            console.log("Assigning task to user:", user_id);
                                            
                                            // Assign task to employee using user_id
                                            frappe.call({
                                                method: 'frappe.desk.form.assign_to.add',
                                                args: {
                                                    assign_to: [user_id],
                                                    doctype: 'Task',
                                                    name: task_name,
                                                    description: `Task assigned from Daily Work Allocation: ${frm.doc.name} (Date: ${allocation_date})`
                                                },
                                                callback: function(assign_response) {
                                                    console.log("Task assignment result:", assign_response);
                                                    
                                                    if (assign_response && assign_response.message) {
                                                        frappe.show_alert({
                                                            message: `Task "${work_item.work_title}" created and assigned to ${employee_name} for ${allocation_date}`,
                                                            indicator: 'green'
                                                        });
                                                    }
                                                }
                                            });
                                        } else {
                                            frappe.show_alert({
                                                message: `Task "${work_item.work_title}" created successfully for ${allocation_date} (no user assignment)`,
                                                indicator: 'green'
                                            });
                                        }
                                    } else {
                                        console.error("Task creation failed:", task_response);
                                        frappe.show_alert({
                                            message: `Failed to create task "${work_item.work_title}"`,
                                            indicator: 'red'
                                        });
                                    }
                                },
                                error: function(error) {
                                    console.error("Task creation error:", error);
                                    frappe.show_alert({
                                        message: `Error creating task: ${error.message || 'Unknown error'}`,
                                        indicator: 'red'
                                    });
                                }
                            });
                        }
                    });
                });
            }
        });
    }
});

